internal object CallsStreamsUpdateCallsStreamsOperation {
    /**
     * Stops a Stream associated with a call. Set `Status` to `stopped`, and identify the Stream by its SID or the name used when it was created.
     *
     * Stop a Stream using either the SID of the Stream resource or the `name` used when creating the resource
     *
     * @param accountSid The SID of the Account that created this Stream resource.
     * @param callSid The SID of the Call the Stream resource is associated with.
     * @param sid The SID or the `name` of the Stream resource to be stopped
     */
    fun updateCallsStreams(clientConfig: ClientConfig, accountSid: String, callSid: String, sid: String, status: StreamEnumUpdateStatus, options: RequestOptions? = null): ApiV2010AccountCallStream {
        Validation.validateLength("AccountSid", accountSid, Validation.LengthOpts(min = 34, max = 34))
        Validation.validatePattern("AccountSid", accountSid, "^AC[0-9a-fA-F]{32}$")

        Validation.validateLength("CallSid", callSid, Validation.LengthOpts(min = 34, max = 34))
        Validation.validatePattern("CallSid", callSid, "^CA[0-9a-fA-F]{32}$")

        return SdkClient.request<ApiV2010AccountCallStream>(SdkClient.RequestSpec("POST", "/2010-04-01/Accounts/${SdkClient.encodePathSegment(accountSid)}/Calls/${SdkClient.encodePathSegment(callSid)}/Streams/${SdkClient.encodePathSegment(sid)}.json", config = clientConfig, body = SdkClient.bodyMap("Status" to (status)), contentType = "application/x-www-form-urlencoded", operationId = "updateCallsStreams", decoder = SdkClient.ResponseDecoder.JSON, options = options)).data
    }
}
